mapper.select:
SELECT uid,user_name,real_name,mobile,user_state,last_login_time,head_icon,
last_login_ip,login_count,user_account,create_time,update_time,email
FROM sys_user_info sui
WHERE delete_state=1 AND user_account not in ('admin')

    AND sui.user_state=#{params.state}


    AND sui.${params.searchType} LIKE concat('%',#{params.searchKeyword},'%')


    AND last_login_time >=#{params.startTime}


    AND last_login_time <=#{params.endTime}



    AND uid in
    (SELECT sru.user_id FROM  sys_role_user sru WHERE sru.role_id in  (

            #{roleId}

    ))


ORDER BY update_time DESC
